export const FILES = {"/manifest.webmanifest":["application/manifest+json","{\"name\": \"HaniaDat · זמני היום, שבת וחגים\", \"short_name\": \"HaniaDat\", \"description\": \"התאריך העברי, זמני היום, הזמן הבא, מצפן לכותל וזמני שבת וחג לפי העיר.\", \"lang\": \"he\", \"dir\": \"rtl\", \"id\": \"/\", \"start_url\": \"/\", \"scope\": \"/\", \"display\": \"standalone\", \"background_color\": \"#1A130E\", \"theme_color\": \"#1A130E\", \"icons\": [{\"src\": \"/icons/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any maskable\"}, {\"src\": \"/icons/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any maskable\"}]}"],"/install.js":["text/javascript; charset=utf-8","// \"Install as an app\" bar, shown on phones when the site is not already installed.\n// Android/Chrome: the browser's own install prompt. iPhone: how to add it from Safari's Share menu.\n// Closing it hides it for 30 days. Works under a strict CSP (no inline styles or scripts).\n(function () {\n  var s = document.currentScript, name = (s && s.dataset.name) || document.title.split(/[·|-]/)[0].trim();\n  var color = (s && s.dataset.color) || \"#0E6B5C\", KEY = \"hania-install-snooze\";\n  var ua = navigator.userAgent || \"\", ios = /iphone|ipad|ipod/i.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);\n  var phone = ios || /android|mobile/i.test(ua);\n  var standalone = (window.matchMedia && matchMedia(\"(display-mode: standalone)\").matches) || navigator.standalone === true;\n  var snoozed = false;\n  try { snoozed = Number(localStorage.getItem(KEY) || 0) > Date.now(); } catch (e) {}\n  var deferred = null, bar = null;\n  window.addEventListener(\"beforeinstallprompt\", function (e) { e.preventDefault(); deferred = e; if (bar) setMode(); else maybeShow(); });\n  window.addEventListener(\"appinstalled\", function () { hide(); });\n  function el(tag, css, text) { var n = document.createElement(tag); for (var k in css) n.style[k] = css[k]; if (text) n.textContent = text; return n; }\n  var msg, btn;\n  function setMode() {\n    if (deferred) { msg.textContent = \"אפשר להתקין את \" + name + \" כאפליקציה בטלפון\"; btn.hidden = false; }\n    else if (ios) { msg.textContent = \"להוספה כאפליקציה: לוחצים על כפתור השיתוף (ריבוע עם חץ למעלה) ואז \\\"הוספה למסך הבית\\\"\"; btn.hidden = true; }\n    else { msg.textContent = \"להוספה כאפליקציה: בתפריט הדפדפן ⋮ בוחרים \\\"הוספה למסך הבית\\\"\"; btn.hidden = true; }\n  }\n  function hide() { if (bar) bar.remove(); bar = null; }\n  function maybeShow() {\n    if (bar || standalone || snoozed || !phone || !document.body) return;\n    bar = el(\"div\", { position: \"fixed\", insetInline: \"10px\", bottom: \"calc(10px + env(safe-area-inset-bottom))\", zIndex: \"2147483000\", display: \"flex\", alignItems: \"center\", gap: \"10px\", padding: \"10px 12px\", borderRadius: \"14px\", background: \"#fff\", color: \"#13201B\", boxShadow: \"0 6px 24px rgba(0,0,0,.18)\", border: \"1px solid #DCE3DF\", font: \"600 14px/1.35 system-ui,-apple-system,'Segoe UI',Arial,sans-serif\", direction: \"rtl\" });\n    bar.setAttribute(\"role\", \"region\"); bar.setAttribute(\"aria-label\", \"התקנת האפליקציה\");\n    var icon = el(\"span\", { flex: \"none\", width: \"34px\", height: \"34px\", borderRadius: \"9px\", background: color, color: \"#fff\", display: \"grid\", placeItems: \"center\", fontSize: \"18px\" }, \"⇩\");\n    msg = el(\"span\", { flex: \"1\" });\n    btn = el(\"button\", { flex: \"none\", border: \"0\", borderRadius: \"10px\", padding: \"9px 14px\", background: color, color: \"#fff\", font: \"inherit\", cursor: \"pointer\" }, \"התקנה\");\n    btn.type = \"button\";\n    btn.onclick = function () { if (!deferred) return; deferred.prompt(); deferred.userChoice.then(function (c) { deferred = null; if (c && c.outcome === \"accepted\") hide(); else setMode(); }); };\n    var x = el(\"button\", { flex: \"none\", border: \"0\", background: \"transparent\", color: \"#5C6B65\", fontSize: \"22px\", lineHeight: \"1\", padding: \"4px 6px\", cursor: \"pointer\" }, \"×\");\n    x.type = \"button\"; x.setAttribute(\"aria-label\", \"סגירה\");\n    x.onclick = function () { try { localStorage.setItem(KEY, String(Date.now() + 30 * 864e5)); } catch (e) {} snoozed = true; hide(); };\n    bar.append(icon, msg, btn, x); setMode(); document.body.appendChild(bar);\n  }\n  // Give the browser a moment to offer its own prompt, then show the right version.\n  function start() { setTimeout(maybeShow, deferred ? 0 : 2500); }\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", start); else start();\n})();\n"],"/sw.js":["text/javascript; charset=utf-8","// HaniaShabbat offline: the page from the network when there is one, from the cache when not.\n// Candle-lighting reminders arrive as an empty push; the message waits on the server.\nconst C = \"haniadat-v2\", FILES = [\"/\", \"/manifest.webmanifest\", \"/icons/icon-192.png\", \"/install.js\", \"/hebcal.js\", \"/parasha.js\", \"/tefila.js\"];\nself.addEventListener(\"install\", (e) => { e.waitUntil(caches.open(C).then((c) => c.addAll(FILES)).then(() => self.skipWaiting())); });\nself.addEventListener(\"activate\", (e) => { e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== C).map((k) => caches.delete(k)))).then(() => self.clients.claim())); });\nself.addEventListener(\"fetch\", (e) => {\n  const u = new URL(e.request.url);\n  if (e.request.method !== \"GET\" || u.origin !== location.origin || u.pathname.startsWith(\"/api/\")) return;\n  e.respondWith(fetch(e.request).then((r) => { if (r.ok) { const copy = r.clone(); caches.open(C).then((c) => c.put(e.request, copy)); } return r; })\n    .catch(() => caches.match(e.request).then((r) => r || caches.match(\"/\"))));\n});\nself.addEventListener(\"push\", (e) => {\n  e.waitUntil((async () => {\n    let m = null;\n    try {\n      const sub = await self.registration.pushManager.getSubscription();\n      const r = await fetch(\"/api/shabbat/msg\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ endpoint: sub && sub.endpoint }) });\n      m = r.ok ? await r.json() : null;\n    } catch { m = null; }\n    if (!m || !m.title) m = { title: \"HaniaDat\", body: \"תזכורת לזמן שבחרתם.\", url: \"/\" };\n    await self.registration.showNotification(m.title, { body: m.body, icon: \"/icons/icon-192.png\", badge: \"/icons/icon-192.png\", lang: \"he\", dir: \"rtl\", tag: \"shabbat\", renotify: true, vibrate: [120, 80, 120],\n      data: { url: m.url || \"/\", d: m.d || \"\" } });\n  })());\n});\nself.addEventListener(\"notificationclick\", (e) => {\n  e.notification.close();\n  const data = e.notification.data || {};\n  const url = new URL(data.url || \"/\", self.location.origin).href;\n  e.waitUntil(self.clients.matchAll({ type: \"window\", includeUncontrolled: true }).then((ws) => {\n    for (const w of ws) if (w.url.startsWith(self.location.origin) && \"focus\" in w) return w.navigate(url).then((x) => (x || w).focus());\n    return self.clients.openWindow(url);\n  }));\n});\n"],"/parasha.js":["text/javascript; charset=utf-8","// HaniaShabbat: a few lines for each weekly portion. Hebcal names (en) -> [Hebrew name, in short, a thought for the table].\n// The thoughts are short and general, meant to open a conversation at the Shabbat table, not as a ruling.\nwindow.PARASHA = {\n  \"Bereshit\": [\"בראשית\", \"בריאת העולם בשישה ימים והשבת, אדם וחוה בגן עדן, קין והבל, ועד דור נח.\", \"העולם נברא במילים: \\\"ויאמר אלוהים ויהי\\\". גם אצלנו מילה טובה יכולה לבנות עולם שלם, ומילה רעה להרוס. איזו מילה טובה נגיד השבוע?\"],\n  \"Noach\": [\"נח\", \"המבול, התיבה, הקשת בענן, ומגדל בבל.\", \"נח בנה תיבה במשך שנים, כשכולם סביבו לא האמינו. לפעמים צריך אומץ לעשות את הדבר הנכון גם כשאף אחד לא מצטרף.\"],\n  \"Lech-Lecha\": [\"לך לך\", \"אברהם עוזב את ארצו ואת בית אביו והולך לארץ כנען, והבטחת הארץ והזרע.\", \"\\\"לך לך\\\" אפשר לקרוא גם \\\"לך אל עצמך\\\". כל יציאה לדרך חדשה היא גם הזדמנות לגלות מי אנחנו באמת.\"],\n  \"Vayera\": [\"וירא\", \"אברהם מכניס אורחים, הבשורה על לידת יצחק, הפיכת סדום ועקדת יצחק.\", \"אברהם רץ לקראת האורחים ביום החם ביותר, כשהוא עוד כואב. הכנסת אורחים מתחילה ברצון לשמח אחרים, גם כשלא נוח לנו.\"],\n  \"Chayei Sara\": [\"חיי שרה\", \"מות שרה וקניית מערת המכפלה, ואליעזר מוצא את רבקה ליצחק.\", \"אליעזר זיהה את רבקה לפי החסד שלה: היא השקתה גם את הגמלים בלי שביקשו. מידה טובה נמדדת במה שעושים בלי שמבקשים.\"],\n  \"Toldot\": [\"תולדות\", \"לידת יעקב ועשו, מכירת הבכורה, ויעקב מקבל את ברכת יצחק.\", \"שני תאומים מאותו בית יצאו שונים כל כך. כל ילד צריך את הדרך שלו, ו\\\"חנוך לנער על פי דרכו\\\".\"],\n  \"Vayetzei\": [\"ויצא\", \"חלום הסולם, יעקב אצל לבן, נישואיו לרחל וללאה ולידת השבטים.\", \"יעקב התעורר מהחלום ואמר: \\\"אכן יש ה׳ במקום הזה ואנכי לא ידעתי\\\". לפעמים הדבר הטוב נמצא ממש לידנו, ורק צריך לשים לב.\"],\n  \"Vayishlach\": [\"וישלח\", \"יעקב נפגש עם עשו, נאבק עם המלאך ומקבל את השם ישראל.\", \"לפני הפגישה עם עשו יעקב התכונן בשלוש דרכים: מתנה, תפילה והכנה לקרב. לכל אתגר כדאי להגיע מוכנים מכמה כיוונים.\"],\n  \"Vayeshev\": [\"וישב\", \"יוסף וחלומותיו, האחים מוכרים אותו, ויוסף בבית פוטיפר ובכלא.\", \"גם בכלא יוסף שם לב שהשרים נראים עצובים ושאל לשלומם. מהשאלה הקטנה הזו התחילה הדרך שלו לגדולה.\"],\n  \"Miketz\": [\"מקץ\", \"יוסף פותר את חלומות פרעה, מתמנה למשנה למלך, והאחים יורדים למצרים לקנות אוכל.\", \"יוסף תכנן שבע שנים קדימה: אוסף בשנים הטובות בשביל השנים הקשות. גם בבית, מה שחוסכים היום עוזר מחר.\"],\n  \"Vayigash\": [\"ויגש\", \"יהודה ניגש אל יוסף, יוסף מתגלה לאחיו, ויעקב יורד למצרים.\", \"יהודה, שפעם הציע למכור את יוסף, מוכן עכשיו להיות עבד במקום בנימין. אנשים יכולים להשתנות ולתקן.\"],\n  \"Vayechi\": [\"ויחי\", \"יעקב מברך את בני יוסף ואת השבטים לפני מותו, ומותם של יעקב ויוסף.\", \"יעקב בירך כל בן בברכה אחרת, לפי מה שמיוחד בו. ברכה טובה רואה את האדם כמו שהוא.\"],\n  \"Shemot\": [\"שמות\", \"שעבוד מצרים, לידת משה, הסנה הבוער והשליחות לפרעה.\", \"משה ראה סנה בוער ו\\\"סר לראות\\\". הוא עצר בשביל דבר שאחרים עברו לידו. גדולה מתחילה בסקרנות.\"],\n  \"Vaera\": [\"וארא\", \"משה ואהרן מול פרעה, ושבע המכות הראשונות.\", \"פרעה הבטיח לשחרר כל פעם שהמכה הייתה קשה, ושכח כשהיא עברה. קל להבטיח ברגע קשה, וחשוב לזכור את ההבטחה אחר כך.\"],\n  \"Bo\": [\"בא\", \"שלוש המכות האחרונות, קורבן פסח ויציאת מצרים.\", \"המצווה הראשונה שקיבל עם ישראל היא לספור את החודשים. מי שיוצא לחירות מתחיל קודם כול לנהל את הזמן שלו.\"],\n  \"Beshalach\": [\"בשלח\", \"קריעת ים סוף, שירת הים, המן במדבר ומלחמת עמלק.\", \"את המן לקחו כל יום רק לאותו יום, ובשישי לחם משנה לשבת. לומדים לסמוך ולא לאגור בלי סוף.\"],\n  \"Yitro\": [\"יתרו\", \"יתרו מייעץ למשה למנות שופטים, ומעמד הר סיני ועשרת הדיברות.\", \"משה, המנהיג הגדול, הקשיב לעצה מחותנו יתרו. גם הגדולים ביותר צריכים לדעת לקבל עצה.\"],\n  \"Mishpatim\": [\"משפטים\", \"חוקים בין אדם לחברו: נזיקין, שמירה על החלש, הגר, היתום והאלמנה.\", \"מיד אחרי עשרת הדיברות מגיעים חוקים \\\"קטנים\\\" של שכנים, כספים ונזקים. האמונה נבחנת ביחס היומיומי לאנשים.\"],\n  \"Terumah\": [\"תרומה\", \"הציווי לבנות את המשכן ואת כליו: הארון, השולחן והמנורה.\", \"\\\"ועשו לי מקדש ושכנתי בתוכם\\\", בתוכם ולא בתוכו. כל בית יכול להיות מקום קטן של קדושה.\"],\n  \"Tetzaveh\": [\"תצווה\", \"בגדי הכהנים, שמן המנורה וחנוכת הכהנים.\", \"השמן למנורה היה \\\"זך כתית\\\", בלי פשרות. לפעמים דבר קטן שעושים בדיוק ובאהבה מאיר הכי חזק.\"],\n  \"Ki Tisa\": [\"כי תשא\", \"מחצית השקל, חטא העגל, הלוחות השניים ושלוש־עשרה מידות הרחמים.\", \"אחרי חטא העגל ניתנו לוחות שניים. תמיד אפשר להתחיל מחדש.\"],\n  \"Vayakhel\": [\"ויקהל\", \"שבת, ובני ישראל מביאים בשמחה תרומה לבניית המשכן.\", \"העם הביא כל כך הרבה עד שהיה צריך לבקש מהם להפסיק. כשכולם נותנים מהלב, נוצר שפע.\"],\n  \"Pekudei\": [\"פקודי\", \"חשבון חומרי המשכן, בגדי הכהנים והקמת המשכן.\", \"משה מסר דין וחשבון על כל גרם זהב, אף שאיש לא חשד בו. שקיפות בונה אמון.\"],\n  \"Vayikra\": [\"ויקרא\", \"דיני הקורבנות.\", \"המילה \\\"ויקרא\\\" נכתבת עם א׳ קטנה. אומרים שמשה, הענו מכל אדם, ביקש להקטין את עצמו.\"],\n  \"Tzav\": [\"צו\", \"המשך דיני הקורבנות, האש התמידה על המזבח וחנוכת הכהנים.\", \"\\\"אש תמיד תוקד על המזבח, לא תכבה\\\". התלהבות צריך לשמור כל יום מחדש, גם בימים רגילים.\"],\n  \"Shmini\": [\"שמיני\", \"היום השמיני לחנוכת המשכן, מות נדב ואביהוא, ודיני מאכלות מותרים ואסורים.\", \"אחרי האסון כתוב \\\"וידום אהרן\\\". לפעמים התגובה הנכונה לכאב היא שקט, ואין צורך במילים.\"],\n  \"Tazria\": [\"תזריע\", \"דיני היולדת ונגעי הצרעת.\", \"חז״ל קשרו את הצרעת ללשון הרע. מה שאומרים על אחרים משפיע קודם כול עלינו.\"],\n  \"Metzora\": [\"מצורע\", \"טהרת המצורע ונגעי הבתים.\", \"המצורע היה יוצא מחוץ למחנה וחוזר בטהרה. גם אחרי ריחוק אפשר לחזור, והקהילה צריכה לדעת לקבל.\"],\n  \"Achrei Mot\": [\"אחרי מות\", \"עבודת הכהן הגדול ביום הכיפורים.\", \"ביום הכיפורים הכהן הגדול מבקש סליחה קודם על עצמו, אחר כך על ביתו, ורק אז על כל העם. תיקון מתחיל מעצמנו.\"],\n  \"Kedoshim\": [\"קדושים\", \"\\\"קדושים תהיו\\\", ומצוות רבות, ביניהן \\\"ואהבת לרעך כמוך\\\".\", \"רבי עקיבא אמר ש\\\"ואהבת לרעך כמוך\\\" הוא כלל גדול בתורה. מה הדבר האחד שאפשר לעשות השבוע בשביל מישהו אחר?\"],\n  \"Emor\": [\"אמור\", \"דיני הכהנים ומועדי השנה: שבת, פסח, שבועות, ראש השנה, יום כיפור וסוכות.\", \"המועדים נקראים \\\"מקראי קודש\\\", הזמנות. כל חג הוא הזמנה לעצור ולהיפגש, עם המשפחה ועם עצמנו.\"],\n  \"Behar\": [\"בהר\", \"שנת השמיטה, שנת היובל, ועזרה לאח שמך ידו.\", \"בשנת השמיטה הארץ נחה וכולם אוכלים מאותם פירות. מנוחה ושוויון הולכים יחד.\"],\n  \"Bechukotai\": [\"בחוקותי\", \"הברכות למי שהולך בדרך התורה, והתוכחה.\", \"\\\"אם בחוקותי תלכו\\\", ללכת ולא לעמוד. החיים הם תנועה מתמדת קדימה.\"],\n  \"Bamidbar\": [\"במדבר\", \"מפקד בני ישראל וסידור השבטים סביב המשכן.\", \"כל אחד נספר בשמו, וכל שבט קיבל מקום משלו סביב המשכן. לכל אחד יש מקום, ובלעדיו החשבון לא שלם.\"],\n  \"Nasso\": [\"נשא\", \"תפקידי הלויים, הנזיר, ברכת כהנים ומתנות הנשיאים.\", \"כל שנים־עשר הנשיאים הביאו בדיוק אותה מתנה, והתורה מפרטת את כולה פעמיים־עשרה. כל אחד מביא את אותו דבר בדרך שלו, וזה חשוב.\"],\n  \"Beha'alotcha\": [\"בהעלותך\", \"הדלקת המנורה, פסח שני, המסעות במדבר והמתאוננים.\", \"אנשים שלא הספיקו להקריב פסח ביקשו הזדמנות, וקיבלו פסח שני. אף פעם לא מאוחר מדי.\"],\n  \"Sh'lach\": [\"שלח לך\", \"שילוח המרגלים לארץ כנען והחזרה עם דיבה על הארץ.\", \"המרגלים ראו את אותה ארץ וחזרו עם סיפורים שונים. הרבה תלוי באיך שאנחנו בוחרים להסתכל.\"],\n  \"Korach\": [\"קורח\", \"מחלוקת קורח ועדתו נגד משה ואהרן, ומטה אהרן שפורח.\", \"מחלוקת שהיא לשם שמיים מתקיימת, ומחלוקת קורח לא. אפשר להתווכח, אבל השאלה היא בשביל מה.\"],\n  \"Chukat\": [\"חוקת\", \"פרה אדומה, מות מרים ואהרן, מי מריבה ונחש הנחושת.\", \"כשמרים נפטרה נגמרו המים. לפעמים מבינים כמה מישהו נתן רק כשהוא כבר לא שם. כדאי להגיד תודה מוקדם.\"],\n  \"Balak\": [\"בלק\", \"בלעם נשלח לקלל את ישראל ומברך אותם במקום.\", \"בלעם בא לקלל וראה \\\"מה טובו אוהליך יעקב\\\". מבט טוב יכול להפוך קללה לברכה.\"],\n  \"Pinchas\": [\"פנחס\", \"ברית השלום לפנחס, בנות צלפחד, מינוי יהושע וקורבנות המועדים.\", \"בנות צלפחד ביקשו נחלה בכבוד ובאומץ, והתורה קבעה שהן צודקות. שווה לשאול כשמשהו נראה לא הוגן.\"],\n  \"Matot\": [\"מטות\", \"דיני נדרים, מלחמת מדיין ובני גד וראובן מבקשים להתיישב בעבר הירדן.\", \"\\\"לא יחל דברו, ככל היוצא מפיו יעשה\\\". מילה שנותנים צריך לקיים.\"],\n  \"Masei\": [\"מסעי\", \"רשימת המסעות במדבר, גבולות הארץ וערי המקלט.\", \"התורה מונה את כל 42 המסעות, גם את הקשים. כל תחנה בדרך היא חלק מהסיפור.\"],\n  \"Devarim\": [\"דברים\", \"משה פותח את נאומו לפני מותו וחוזר על המסע במדבר.\", \"משה, שאמר פעם \\\"לא איש דברים אנוכי\\\", נואם עכשיו ספר שלם. אנשים גדלים ומתפתחים.\"],\n  \"Vaetchanan\": [\"ואתחנן\", \"תפילת משה להיכנס לארץ, עשרת הדיברות וקריאת שמע.\", \"משה התפלל שוב ושוב, ולמרות התשובה השלילית לא הפסיק לאהוב ולהנהיג. אפשר לקבל \\\"לא\\\" ולהמשיך בדרך.\"],\n  \"Eikev\": [\"עקב\", \"שבחי הארץ, ברכת המזון וזכירת המדבר.\", \"\\\"ואכלת ושבעת וברכת\\\": מברכים דווקא אחרי ששבענו, כשהכי קל לשכוח להגיד תודה.\"],\n  \"Re'eh\": [\"ראה\", \"הברכה והקללה, המקום שה׳ יבחר, צדקה ושלושת הרגלים.\", \"\\\"פתוח תפתח את ידך\\\": נותנים ביד פתוחה ובלב פתוח, לא בקמצנות.\"],\n  \"Shoftim\": [\"שופטים\", \"מינוי שופטים ושוטרים, המלך, הנביא, ערי מקלט ודיני מלחמה.\", \"\\\"צדק צדק תרדוף\\\", המילה כתובה פעמיים. גם הדרך להגיע לצדק צריכה להיות צודקת.\"],\n  \"Ki Teitzei\": [\"כי תצא\", \"מצוות רבות בחיי היומיום, ביניהן השבת אבדה, שילוח הקן ומעקה לגג.\", \"\\\"לא תוכל להתעלם\\\": אם ראית משהו של חבר שהלך לאיבוד, זה גם עניין שלך.\"],\n  \"Ki Tavo\": [\"כי תבוא\", \"ביכורים, הברכות והקללות בהר גריזים והר עיבל.\", \"מביאים ביכורים ואומרים תודה על כל הדרך שעברנו. הכרת הטוב מתחילה בלזכור מאיפה באנו.\"],\n  \"Nitzavim\": [\"נצבים\", \"כל העם עומד יחד בברית, והבחירה בחיים.\", \"\\\"ובחרת בחיים\\\". כל יום מחדש יש לנו בחירה, וזו המתנה הכי גדולה.\"],\n  \"Vayeilech\": [\"וילך\", \"משה ביומו האחרון מעביר את ההנהגה ליהושע ומצוות כתיבת ספר תורה.\", \"המצווה האחרונה בתורה היא שכל אחד יכתוב ספר תורה. כל אחד יכול להוסיף שורה משלו לסיפור.\"],\n  \"Ha'azinu\": [\"האזינו\", \"שירת משה לעם ישראל.\", \"משה בחר להיפרד בשירה. לפעמים שיר אומר את מה שהמילים לבד לא מצליחות.\"],\n  \"Vezot Haberakhah\": [\"וזאת הברכה\", \"ברכת משה לשבטים ומותו. נקראת בשמחת תורה.\", \"התורה מסתיימת ומיד מתחילים מבראשית. הלימוד לא נגמר אף פעם.\"],\n};\n"]};
export const IMAGES = {};
